bsolute font URLs and\nmanually injecting @font-face into document.head to bypass CSS scoping.","tree":{"sha":"ff439596573aaf0d55bd39c238f4546865ef60c2","url":"https://api.github.com/repos/Orange-001/micro-frontend-demo/git/trees/ff439596573aaf0d55bd39c238f4546865ef60c2"},"url":"https://api.github.com/repos/Orange-001/micro-frontend-demo/git/commits/7dd5c155cd1fb1c0dd86bed25b60f13bb3f402ad","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/6297453?v=4","events_url":"https://api.github.com/users/sps123/events{/privacy}","followers_url":"https://api.github.com/users/sps123/followers","following_url":"https://api.github.com/users/sps123/following{/other_user}","gists_url":"https://api.github.com/users/sps123/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sps123","id":6297453,"login":"sps123","node_id":"MDQ6VXNlcjYyOTc0NTM=","organizations_url":"https://api.github.com/users/sps123/orgs","received_events_url":"https://api.github.com/users/sps123/received_events","repos_url":"https://api.github.com/users/sps123/repos","site_admin":false,"starred_url":"https://api.github.com/users/sps123/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sps123/subscriptions","type":"User","url":"https://api.github.com/users/sps123","user_view_type":"public"},"html_url":"https://github.com/Orange-001/micro-frontend-demo/commit/7dd5c155cd1fb1c0dd86bed25b60f13bb3f402ad","node_id":"C_kwDOR1y7-toAKDdkZDVjMTU1Y2QxZmIxYzBkZDg2YmVkMjViNjBmMTNiYjNmNDAyYWQ","parents":[{"html_url":"https://github.com/Orange-001/micro-frontend-demo/commit/99da8932231c6aa12a43df3aecc94b9fe0f80fce","sha":"99da8932231c6aa12a43df3aecc94b9fe0f80fce","url":"https://api.github.com/repos/Orange-001/micro-frontend-demo/commits/99da8932231c6aa12a43df3aecc94b9fe0f80fce"}],"sha":"7dd5c155cd1fb1c0dd86bed25b60f13bb3f402ad","url":"https://api.github.com/repos/Orange-001/